// Resolve exactly one special event on arrival; no infinite chaining.
async function moveWithSpecial(playerIndex,steps){
  const player=participants[playerIndex];
  await new Promise(resolve=>movePawn(playerIndex,player.house+steps,resolve));
  const event=getSpecial(player.house);
  if(!event)return null;
  const oldHouse=player.house;
  const destination=Math.max(0,Math.min(59,oldHouse+event.delta));
  const moveLabel=event.delta>0?'avance':'volte';
  const user=playerIndex===0;
  if(user)$('#hudStatus').textContent=`${event.label}! Seu ratinho ${moveLabel} ${Math.abs(event.delta)} casas`;
  showToast(`${user?'Você':player.name}: ${event.label} — ${event.delta>0?'+':''}${event.delta} casas!`);
  await delay(330);
  await new Promise(resolve=>movePawn(playerIndex,destination,resolve));
  return {event,from:oldHouse+1,to:destination+1};
}
